<script setup lang="ts">
import { ref, onMounted } from 'vue'
import { api } from '../../api'
import { t } from '../../locales'
import { oauthRedirectUrl, openOAuthUrl } from '../../native/oauth'
import '../../styles/app.scss'
const mode = ref<'menu' | 'password' | '2fa'>('menu')
const oldPassword = ref(''); const newPassword = ref(''); const confirm = ref(''); const code = ref('')
const enabled = ref(false); const secret = ref(''); const googleBound = ref(false); const microsoftBound = ref(false); const bindingLoading = ref<'google' | 'microsoft' | ''>('')
onMounted(async () => { try { const data: any = await api.get2fa(); enabled.value = Boolean(data?.enabled || data?.status); secret.value = data?.secret || '' } catch {} try { const data: any = await api.bindStatus(); googleBound.value = Boolean(data?.googleBound); microsoftBound.value = Boolean(data?.microsoftBound) } catch {} })
async function savePassword() { if (!oldPassword.value || newPassword.value.length < 6 || newPassword.value !== confirm.value) return uni.showToast({ title: t('请检查密码输入'), icon: 'none' }); try { await api.changePassword({ currentPassword: oldPassword.value, newPassword: newPassword.value, confirmPassword: confirm.value }); uni.showToast({ title: t('密码已修改，请重新登录'), icon: 'none' }); mode.value = 'menu' } catch (error: any) { uni.showToast({ title: error?.message || t('修改失败'), icon: 'none' }) } }
async function save2fa() { if (code.value.length !== 6) return uni.showToast({ title: t('请输入 6 位验证码'), icon: 'none' }); try { if (enabled.value) await api.disable2fa({ type: 1, twoFactorCode: code.value }); else await api.update2fa({ type: 1, secret: secret.value, twoFactorCode: code.value, emailCode: '' }); enabled.value = !enabled.value; code.value = ''; mode.value = 'menu'; uni.showToast({ title: enabled.value ? t('2FA 已开启') : t('2FA 已关闭'), icon: 'none' }) } catch (error: any) { uni.showToast({ title: error?.message || t('操作失败'), icon: 'none' }) } }
async function openBinding(provider: 'google' | 'microsoft') { if (provider === 'google' ? googleBound.value : microsoftBound.value) return; bindingLoading.value = provider; try { const result: any = await api.oauthAuth(provider, oauthRedirectUrl(provider, 'binding')); if (!result?.authUrl) throw new Error(t('接口未返回授权地址')); await openOAuthUrl(result.authUrl) } catch (error: any) { uni.showToast({ title: error?.message || t('发起绑定失败'), icon: 'none' }) } finally { bindingLoading.value = '' } }
async function unbind(provider: 'google' | 'microsoft') { try { if (provider === 'google') await api.unbindGoogle(); else await api.unbindMicrosoft(); if (provider === 'google') googleBound.value = false; else microsoftBound.value = false; uni.showToast({ title: t('解绑成功'), icon: 'none' }) } catch (error: any) { uni.showToast({ title: error?.message || t('解绑失败'), icon: 'none' }) } }
</script>
<template><view class="inner-page"><view class="inner-nav"><text class="back" @click="uni.navigateBack()">‹</text><text class="nav-title">{{t('安全设置')}}</text></view><view class="inner-main"><view v-if="mode==='menu'" class="settings-list"><view class="settings-row" @click="mode='password'"><view><text class="settings-icon">♢</text><text>{{t('修改密码')}}</text></view><text class="list-arrow">›</text></view><view class="settings-row" @click="mode='2fa'"><view><text class="settings-icon">♙</text><text>{{t('2FA 双重验证')}}</text></view><text class="settings-hint">{{enabled?t('已开启'):t('未开启')}}　›</text></view><view class="settings-row"><view><text class="settings-icon">G</text><text>{{t('Google 绑定')}}</text></view><button class="bind-button" :disabled="bindingLoading==='google'" @click.stop="googleBound ? unbind('google') : openBinding('google')">{{googleBound?t('解绑'):bindingLoading==='google'?t('处理中'):t('绑定')}}</button></view><view class="settings-row"><view><text class="settings-icon">M</text><text>{{t('Microsoft 绑定')}}</text></view><button class="bind-button" :disabled="bindingLoading==='microsoft'" @click.stop="microsoftBound ? unbind('microsoft') : openBinding('microsoft')">{{microsoftBound?t('解绑'):bindingLoading==='microsoft'?t('处理中'):t('绑定')}}</button></view></view><view v-else-if="mode==='password'" class="inner-card"><view class="form-field"><text class="form-label">{{t('原密码')}}</text><input v-model="oldPassword" class="form-input" password/></view><view class="form-field"><text class="form-label">{{t('新密码')}}</text><input v-model="newPassword" class="form-input" password/></view><view class="form-field"><text class="form-label">{{t('确认新密码')}}</text><input v-model="confirm" class="form-input" password/></view><button class="action-button" @click="savePassword">{{t('保存修改')}}</button></view><view v-else class="inner-card"><view class="notice">{{t('请输入身份验证器中的 6 位动态码')}}</view><view class="form-field" style="margin-top:20rpx"><input v-model="code" class="form-input" maxlength="6" :placeholder="t('输入 6 位验证码')"/></view><button class="action-button" @click="save2fa">{{enabled?t('关闭 2FA'):t('开启 2FA')}}</button></view></view></view></template>
<style scoped>.bind-button{min-width:108rpx;height:58rpx;padding:0 18rpx;border:1rpx solid var(--cf-line);border-radius:10rpx;background:#EFF6FF;color:var(--cf-brand);font-size:21rpx;line-height:58rpx}.bind-button[disabled]{opacity:.6}</style>
